def cantor_numbering(n):
    def sieve(n):
        sieve = [True] * (n + 1)
        for p in range(2, int(n ** 0.5) + 1):
            if sieve[p]:
                for i in range(p * p, n + 1, p):
                    sieve[i] = False
        return [p for p in range(2, n + 1) if sieve[p]]

    def fac(n):
        result = 1
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                result *= i
        return result

    prime_factors = sieve(n)
    numerator = 1
    denominator = 1
    for p in prime_factors:
        numerator *= p
        po = 1
        for i in range(1, int(n / p) + 1):
            po *= p
            denominator *= fac(po)

    return f'{numerator} / {denominator}'

def max_product(num_str, N, K):
    if K == 0:
        return int(num_str)
    if N == 1:
        return int(num_str)
    if K == 1:
        return max(int(num_str[0])*int(num_str[1]), int(num_str[1])*int(num_str[2]))
    left = max_product(num_str[:N//2], N//2, K//2)
    right = max_product(num_str[N//2:], N//2, K//2)
    if K % 2 == 0:
        return left * right
    else:
        return max(left * right, left * int(num_str[N//2]) * right)

