def remaining_trees_after_clearing(l, areas):

    # Initialize a list to store the remaining trees
    remaining_trees = [1] * l

    # Iterate through the list of cleared areas
    for area in areas:

        # Calculate the start and end indices of the current area
        start_idx = area[0] - 1
        end_idx = area[1] - 1

        # Remove the trees along the cleared area
        for i in range(start_idx, end_idx + 1):
            remaining_trees[i] = 0

    # Return the total number of remaining trees
    return sum(remaining_trees)

def max_herb_value(T, M, herbs):
    # Initialize a list to store the maximum values for each time period
    max_values = [0] * (T + 1)

    # Loop through each herb and its time cost and value
    for t, v in herbs:
        # Loop through each time period
        for i in range(T, t - 1, -1):
            # Check if the current time period is within the time limit
            if i >= t:
                # Update the maximum value for the current time period
                max_values[i] = max(max_values[i], max_values[i - t] + v)

    # Return the maximum value for the final time period
    return max_values[T]

def calculate_arrangements(n, m, a):
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if j <= a[i - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]
    return dp[n][m] % (10**6 + 7)

def jinjin_savings_plan(budgets: List[int]) -> int:
